@lru_cache(maxsize=1)
def _bytes_verificados():
    try:
        source = base64.b85decode("".join(_PNG_ASCII85))
        if len(source) != MANIFESTO_F04["size_bytes"]:
            return b""
        if hashlib.sha256(source).hexdigest() != MANIFESTO_F04["sha256"]:
            return b""
        return source
    except (ValueError, TypeError):
        return b""


def carregar_pixmap():
    """Mesma API de F04: (QPixmap, valido); fallback L03 mantido no jogos.py."""
    from PySide6.QtGui import QPixmap
    foto=QPixmap()
    data=_bytes_verificados()
    if not data or not foto.loadFromData(data,"PNG"):
        return foto,False
    if foto.width()!=MANIFESTO_F04["width"] or foto.height()!=MANIFESTO_F04["height"]:
        return QPixmap(),False
    return foto,True
